import {CLAIM_STAGES,TRUST_BANDS,cleanDossier,cleanReview,sourceSignals} from './exhibits.js?v=0.5.0';
import {projects as demos} from './catalog.js?v=0.5.0';
import {createInvitePayload} from './referral.js?v=0.5.0';
import {normalize,cleanProject,backup,mergeBackup,icsEvent} from './model.js?v=0.5.0';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let raw;try{raw=JSON.parse(localStorage.getItem('airdrop-museum-v1'))||{}}catch{raw={}}let state;try{state=normalize(raw,demos)}catch{state=normalize({},demos)}
const nav=[['home','⌂','Museum'],['explore','⌕','Galeri'],['workspace','☑','Portofolio'],['archive','◇','Arsip'],['voices','♧','Suara Pengunjung'],['profile','♙','Profil'],['referral','↗','Ajak']];
const labels={watching:'Pantauan',active:'Berjalan',completed:'Selesai',archived:'Diarsipkan'};
let serverInfo=null,cloudRevision=null,syncBusy=false;
let page='home',query='',category='All',chain='All',sort='featured',mode='all',month=new Date(new Date().getFullYear(),new Date().getMonth(),1),openId=null;
const all=()=>[...demos,...state.custom],project=id=>all().find(p=>p.id===id),rec=p=>state.records[p.id],done=p=>p.tasks.filter((_,i)=>state.done[p.id+':'+i]).length,total=()=>all().reduce((n,p)=>n+done(p),0),today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function persist(text){if(text)state.history.unshift({at:new Date().toISOString(),text});state.history=state.history.slice(0,100);try{localStorage.setItem('airdrop-museum-v1',JSON.stringify(state))}catch{toast('Penyimpanan tidak tersedia. Ekspor backup sebelum menutup aplikasi.')}}
function navigate(id){page=[...nav.map(n=>n[0]),'calendar'].includes(id)?id:'home';query='';category=chain='All';mode='all';location.hash=page;render();window.scrollTo(0,0)}
function intro(title,desc,action=''){return `<div class="intro"><div><span class="eyeline">MUSEUM TERBUKA AIRDROP</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
const empty=(text,button='')=>`<div class="empty">${text}${button}</div>`;
function stats(){const tracked=all().filter(p=>state.saved.includes(p.id)&&rec(p).status!=='archived');return `<div class="stats">${[['◇',tracked.length,'Pameran di portofolio'],['☑',tracked.filter(p=>rec(p).status==='active').length,'Sedang diteliti'],['✓',total(),'Tugas riset selesai'],['▦',tracked.filter(p=>rec(p).due&&rec(p).due>=today()).length,'Tenggat mendatang']].map(([i,n,l])=>`<div class="stat"><span class="stat-icon">${i}</span><div><b>${n}</b><small>${l}</small></div></div>`).join('')}</div>`}
function row(p){const r=rec(p);return `<button class="project-row" data-open="${esc(p.id)}"><span class="row-symbol">${p.symbol}</span><span><b>${esc(p.name)}</b><small>${esc(p.chain)} · ${p.custom?'Personal project':'Demo'} · ${labels[r.status]}</small></span><span class="row-meta">${done(p)}/${p.tasks.length}<small>${r.due||'No deadline'}</small></span><span>↗</span></button>`}
function activity(){return state.history.length?`<ol class="activity">${state.history.slice(0,8).map(h=>`<li><span>${esc(h.text)}</span><time>${esc(new Date(h.at).toLocaleString('id-ID'))}</time></li>`).join('')}</ol>`:empty('Aktivitas riset Anda akan muncul di sini.')}
function card(p){const saved=state.saved.includes(p.id);return `<article class="card"><div class="card-art"><span class="tag">PAMERAN ${String(all().indexOf(p)+1).padStart(3,'0')} · ${p.custom?'CATATAN PRIBADI':'CONTOH FIKTIF'}</span><button class="save ${saved?'saved':''}" data-save="${esc(p.id)}" aria-label="${saved?'Untrack':'Track'} ${esc(p.name)}" aria-pressed="${saved}">${saved?'◆':'◇'}</button><span class="project-symbol">${p.symbol}</span></div><div class="card-body"><div class="card-heading"><h3>${esc(p.name)}</h3></div><p>${esc(p.desc)}</p><div class="exhibit-status"><span>Tinjauan pribadi</span><b>${rec(p).dossier.checkedAt?'Tanggal dicatat':'Belum dicatat'}</b></div><div class="tags"><span class="tag-inline">${esc(p.category)}</span><span class="tag-inline">${esc(p.chain)}</span></div><div class="card-bottom"><span class="evidence-label">◌ Skor kredibilitas: belum tersedia</span><button class="text-btn" data-open="${esc(p.id)}">Lihat pameran ↗</button></div></div></article>`}
function discover(){return intro('Galeri pameran.','Setiap exhibit tetap terlihat. Baca bukti, pahami risiko, tentukan sendiri.',`<button class="primary" id="add-project">+ Add project</button>`)+`<div class="notice" role="note"><b>Semua exhibit bertanda DEMO adalah contoh fiktif, bukan kampanye airdrop nyata.</b> Jangan menghubungkan wallet atau mengirim dana berdasarkan data demo.</div><div class="toolbar"><label class="search"><span>⌕</span><input id="search" type="search" aria-label="Cari proyek" placeholder="Search name, chain, category..."></label><select id="chain" aria-label="Filter chain"><option value="All">All chains</option>${[...new Set(all().map(p=>p.chain))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="mode" aria-label="Sumber proyek"><option value="all">All sources</option><option value="personal">Personal only</option><option value="demo">Demo only</option></select><select id="sort" aria-label="Urutan"><option value="featured">Curated order</option><option value="name">Name A–Z</option></select></div><div class="filters">${['All','Testnet','DeFi','GameFi','Layer 2','RWA','Gaming','AI','Infra','NFT'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div class="section-title"><h2>Project directory</h2><small id="count" aria-live="polite" aria-atomic="true"></small></div><div class="grid" id="project-grid"></div>`}
function updateGrid(){const list=all().filter(p=>(category==='All'||p.category===category)&&(chain==='All'||p.chain===chain)&&(mode==='all'||(mode==='personal'?p.custom:!p.custom))&&[p.name,p.chain,p.category].join(' ').toLowerCase().includes(query.toLowerCase()));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#project-grid').innerHTML=list.length?list.map(card).join(''):empty('Tidak ada proyek yang cocok. Coba filter lain.');$('#count').textContent=list.length+' projects';document.querySelectorAll('[data-category]').forEach(el=>{el.classList.toggle('active',el.dataset.category===category);el.setAttribute('aria-pressed',el.dataset.category===category)})}
function workspace(){const tracked=all().filter(p=>state.saved.includes(p.id)&&rec(p).status!=='archived');return intro('Your personal collection.','Lacak riset, snapshot, dan klaim. Status partisipasi adalah laporan pribadi.',`<button class="secondary" data-nav="calendar">Open calendar ↗</button>`)+`<div class="kanban">${['watching','active','completed'].map(status=>`<section class="lane"><div class="section-title"><h3>${labels[status]}</h3><small>${tracked.filter(p=>rec(p).status===status).length}</small></div>${tracked.filter(p=>rec(p).status===status).map(p=>`<article class="work-card"><button class="work-title" data-open="${esc(p.id)}">${p.symbol} ${esc(p.name)} ↗</button><span class="tag-inline">${esc(CLAIM_STAGES[rec(p).dossier.stage])}</span><span class="tag-inline">${rec(p).priority.toUpperCase()}</span><p>${done(p)}/${p.tasks.length} tasks · ${rec(p).due||'No deadline'}</p><div class="progress"><span style="width:${done(p)/p.tasks.length*100}%"></span></div><p class="note-preview">${esc(rec(p).notes||'Belum ada catatan riset.')}</p><button class="text-btn" data-open="${esc(p.id)}">Manage project →</button></article>`).join('')||empty('Belum ada proyek di tahap ini.')}</section>`).join('')}</div>`}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),start=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate(),due=all().filter(p=>state.saved.includes(p.id)&&rec(p).due&&rec(p).status!=='archived');return intro('Never lose sight of a deadline.','Tanggal di sini adalah target pribadi yang Anda tetapkan, bukan tenggat resmi kampanye.',`<button class="secondary" id="export-calendar">Export calendar ↓</button>`)+`<section class="panel"><div class="section-title"><button class="secondary" data-month="-1" aria-label="Bulan sebelumnya">←</button><h2>${month.toLocaleDateString('id-ID',{month:'long',year:'numeric'})}</h2><button class="secondary" data-month="1" aria-label="Bulan berikutnya">→</button></div><div class="calendar-grid">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(d=>`<b class="weekday">${d}</b>`).join('')}${Array.from({length:start},()=>'<div class="day blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const date=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<div class="day ${date===today()?'today':''}"><span>${i+1}</span>${due.filter(p=>rec(p).due===date).map(p=>`<button data-open="${esc(p.id)}">${esc(p.name)}</button>`).join('')}</div>`}).join('')}</div></section><section class="panel"><h3>All scheduled projects</h3>${due.length?due.sort((a,b)=>rec(a).due.localeCompare(rec(b).due)).map(row).join(''):empty('Atur deadline di detail proyek untuk mulai menjadwalkan riset.')}</section>`}
function archiveLedger(){const list=all().filter(p=>rec(p).status==='archived'),recorded=all().filter(p=>rec(p).cost||rec(p).reward),cost=recorded.reduce((n,p)=>n+rec(p).cost,0),reward=recorded.reduce((n,p)=>n+rec(p).reward,0);return '<div class="section-title"><h2>Personal archive & outcome ledger</h2></div>'+`<div class="stats">${[[list.length,'Archived projects'],[money(cost),'Recorded costs'],[money(reward),'Recorded rewards'],[money(reward-cost),'Net recorded']].map(([n,l])=>`<div class="stat"><div><b>${n}</b><small>${l}</small></div></div>`).join('')}</div><section class="panel"><h3>Archived research</h3>${list.length?list.map(row).join(''):empty('Arsip masih kosong. Arsipkan proyek melalui pengaturan status di detail.')}</section><section class="panel"><h3>Outcome ledger · USD</h3><p>Catatan manual pribadi, bukan saldo wallet atau bukti transaksi.</p>${recorded.length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Cost</th><th>Reward</th><th>Net</th></tr></thead><tbody>${recorded.map(p=>`<tr><td><button class="text-btn" data-open="${esc(p.id)}">${esc(p.name)}</button></td><td>${money(rec(p).cost)}</td><td>${money(rec(p).reward)}</td><td>${money(rec(p).reward-rec(p).cost)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada biaya atau hasil dicatat.')}</section>`}
function profile(){return intro('Your museum pass.','Kelola profil lokal, backup lengkap, dan status integrasi.')+`<div class="split"><section class="panel"><h3>Profil penjelajah</h3><form id="profile-form"><label>Display name<input name="name" value="${esc(state.name)}" maxlength="60" required></label><button class="primary">Simpan profil</button></form><p>Profil lokal browser · ${total()} tugas selesai</p><div class="badge-grid">${[['◇','Researcher',state.saved.length>0],['✓','First steps',total()>0],['✦','Task curator',total()>=12]].map(([s,n,yes])=>`<div class="badge"><strong style="opacity:${yes?1:.3}">${s}</strong>${n}<br>${yes?'Unlocked':'Locked'}</div>`).join('')}</div></section><section class="panel"><h3>Status integrasi</h3><div class="status-row"><b>Cloudflare C0</b><span>Deployed</span></div><div class="status-row"><b>Telegram display SDK</b><span>${window.Telegram?.WebApp?.initData?'Inside Telegram':'Browser mode'}</span></div><div class="status-row"><b>Verified login / sync</b><span>${serverInfo?.sync?'Siap di Telegram':'Menunggu konfigurasi bot'}</span></div><div class="status-row"><b>Wallet / claims</b><span>Tidak terhubung</span></div><p>Data tetap di browser ini. Tidak ada transaksi atau task verification otomatis.</p></section></div>${syncPanel()}<section class="panel"><h3>Privacy & local data</h3><p>Nama, catatan riset, ulasan, tenggat, dan ledger disimpan di browser ini; tidak dikirim ke cloud tanpa tindakan sinkronisasi Anda. Orang lain yang memakai profil browser/perangkat yang sama mungkin dapat mengaksesnya. Jangan simpan seed phrase, private key, token, atau data sensitif.</p><p>Ekspor backup membuat file JSON yang berisi data tersebut. Simpan secara aman dan hapus salinan yang tidak dibutuhkan. Menghapus data situs tidak menghapus file backup yang sudah diunduh.</p><p>Halaman ini memuat Telegram Web App SDK dari telegram.org dan font dari Google Fonts; penyedia dapat menerima metadata koneksi web standar seperti alamat IP dan user-agent.</p><button class="secondary" id="clear-local-data" type="button">Hapus semua data lokal</button></section><section class="panel"><h3>Data portability</h3><p>Ekspor proyek pribadi, checklist, catatan, jadwal, dan pencatatan hasil. Impor menggabungkan progres; pengaturan proyek yang sudah ada tetap dipertahankan.</p><div class="data-actions"><button class="secondary" id="export">Ekspor cadangan penuh ↓</button><label class="secondary import-label">Impor cadangan ↑<input id="import" type="file" accept="application/json,.json"></label></div></section><section class="panel"><h3>Riwayat aktivitas</h3>${activity()}</section>`}
function render(){for(const id of ['desktop-nav','mobile-nav'])$('#'+id).innerHTML=nav.map(([key,icon,label])=>`<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><i aria-hidden="true">${icon}</i>${label}</button>`).join('');$('#page-label').textContent=(nav.find(n=>n[0]===page)?.[2]||'Calendar');$('#app').innerHTML=({home:dashboard,explore:discover,workspace,calendar,archive,voices,profile,referral:invite}[page])();if(page==='explore'){updateGrid();$('#search').value=query;$('#chain').value=chain;$('#mode').value=mode;$('#sort').value=sort}}
function taskList(p){return p.tasks.map((t,i)=>`<button class="task ${state.done[p.id+':'+i]?'done':''}" data-task="${esc(p.id)}:${i}" aria-pressed="${!!state.done[p.id+':'+i]}"><span class="check">${state.done[p.id+':'+i]?'✓':''}</span><span>${esc(t)}</span></button>`).join('')}
function showDetail(id){const p=project(id);if(!p)return;openId=id;const r=rec(p);$('#detail-content').innerHTML=`<div class="detail-top"><button class="close" id="close" aria-label="Tutup detail">×</button><span class="project-symbol">${p.symbol}</span></div><div class="detail-body"><span class="eyeline">${p.custom?'PROYEK PRIBADI':'CONTOH FIKTIF'}</span><h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><div class="exhibit-status"><span>Tinjauan pribadi</span><b>${rec(p).dossier.checkedAt?'Tanggal dicatat':'Belum dicatat'}</b></div><div class="tags"><span class="tag-inline">${esc(p.category)}</span><span class="tag-inline">${esc(p.chain)}</span></div>${p.website?`<p><button class="secondary" data-source="${esc(p.id)}">Periksa sumber ↗</button></p>`:''}<div class="notice">${p.custom?'Sumber ditambahkan sendiri dan belum diverifikasi oleh Airdrop Museum.':'Proyek fiktif untuk demonstrasi. Tidak ada kampanye atau reward nyata.'} Checklist adalah catatan pribadi, bukan bukti eligibility.</div><button class="secondary" data-save="${esc(id)}">${state.saved.includes(id)?'◆ Tersimpan · hapus dari portofolio':'◇ Tambah ke portofolio'}</button>${dossierView(p)}<h3>Panduan partisipasi · ${done(p)}/${p.tasks.length}</h3>${taskList(p)}<form id="record-form" data-id="${esc(id)}"><h3>Catatan portofolio</h3><div class="form-grid"><label>Status<select name="status">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Prioritas<select name="priority">${[['low','Rendah'],['normal','Normal'],['high','Tinggi']].map(([v,label])=>`<option value="${v}" ${r.priority===v?'selected':''}>${label}</option>`).join('')}</select></label><label>Tenggat pribadi<input type="date" name="due" value="${r.due}"></label><label>Biaya · USD<input type="number" name="cost" min="0" max="1000000000" step="0.01" value="${r.cost}"></label><label>Reward aktual · USD<input type="number" name="reward" min="0" max="1000000000" step="0.01" value="${r.reward}"></label></div>${dossierForm(p)}<label>Catatan riset<textarea name="notes" maxlength="5000" rows="5" placeholder="Sources checked, risks, next steps…">${esc(r.notes)}</textarea></label><button class="primary">Simpan riset</button><p class="connection">Status selesai, arsip, dan reward dicatat manual oleh Anda.</p></form>${reviewForm(p)}</div>`;if(!$('#detail').open)$('#detail').showModal()}
function addProject(){if(!$('#project-editor'))document.body.insertAdjacentHTML('beforeend','<dialog id="project-editor"></dialog>');$('#project-editor').innerHTML=`<div class="detail-body"><div class="section-title"><h2>Add a project</h2><button class="secondary" id="close-editor">×</button></div><p>Tambahkan proyek riset Anda. Sumber tidak dianggap terverifikasi otomatis.</p><form id="new-project"><label>Project name<input name="name" maxlength="80" required></label><label>Official source URL<input name="website" type="url" placeholder="https://…" required></label><div class="form-grid"><label>Category<select name="category">${['Testnet','DeFi','GameFi','Layer 2','RWA','Gaming','AI','Infra','NFT'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Chain<input name="chain" maxlength="40" required></label></div><label>Description<textarea name="desc" maxlength="500" rows="2"></textarea></label><label>Research tasks · one per line<textarea name="tasks" maxlength="6000" rows="5" placeholder="Review official documentation\nCheck campaign rules" required></textarea></label><p class="connection">Maksimal 30 tugas. Jangan masukkan seed phrase, private key, atau token.</p><button class="primary">Create & track project</button></form></div>`;$('#project-editor').showModal()}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.nav)return navigate(d.nav);if(d.category){category=d.category;return updateGrid()}if(d.open)return showDetail(d.open);if(d.source)return sourceGate(d.source);if(d.save){const p=project(d.save);if(!p)return;const saved=state.saved.includes(p.id);state.saved=saved?state.saved.filter(id=>id!==p.id):[...state.saved,p.id];if(!saved&&rec(p).status==='archived')rec(p).status='watching';persist(`${saved?'Untracked':'Tracked'} ${p.name}`);render();if($('#detail').open)showDetail(p.id);return}if(d.task){const id=openId,p=project(id);if(!p)return;const form=$('#record-form');if(form){const draft=Object.fromEntries(new FormData(form));state.records[id]={...draft,dossier:cleanDossier(draft)};state=normalize(state,demos)}state.done[d.task]=!state.done[d.task];if(!state.saved.includes(id))state.saved.push(id);persist(`Updated checklist: ${p.name}`);render();showDetail(id);return}if(d.month){month=new Date(month.getFullYear(),month.getMonth()+Number(d.month),1);render();return}if(el.id==='add-project')addProject();if(el.id==='close')$('#detail').close();if(el.id==='close-editor')$('#project-editor').close();if(el.id==='copy-invite')return copyInvite();if(el.id==='share-invite')return shareInvite();if(el.id==='export')download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'airdrop-museum-backup.json','application/json');if(el.id==='export-calendar'){const events=all().filter(p=>state.saved.includes(p.id)&&rec(p).due&&rec(p).status!=='archived').map(p=>icsEvent(p,rec(p)));if(!events.length)return toast('Belum ada deadline untuk diekspor.');download(['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Airdrop Museum//Research Calendar//ID',...events,'END:VCALENDAR'].join('\r\n'),'airdrop-museum.ics','text/calendar')}});
document.addEventListener('click',e=>{if(e.target.id==='clear-local-data'&&confirm('Hapus seluruh proyek, catatan, ulasan, dan progres yang tersimpan di browser ini? File backup yang sudah diunduh tidak akan ikut terhapus.')){localStorage.removeItem('airdrop-museum-v1');state=normalize({},demos);render();toast('Semua data lokal telah dihapus.')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;updateGrid()}});
document.addEventListener('change',async e=>{if(['chain','mode','sort'].includes(e.target.id)){if(e.target.id==='chain')chain=e.target.value;if(e.target.id==='mode')mode=e.target.value;if(e.target.id==='sort')sort=e.target.value;updateGrid()}if(e.target.id==='import'){try{const file=e.target.files?.[0];if(!file)return;if(file.size>1000000)throw Error('Backup melebihi 1 MB.');state=mergeBackup(state,backup(await file.text(),demos),demos);persist('Imported backup');render();toast('Backup berhasil digabungkan.')}catch(err){toast(err.message)}}});
document.addEventListener('submit',e=>{if(!['new-project','record-form','profile-form','review-form'].includes(e.target.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{if(e.target.id==='new-project'){if(state.custom.length>=100)throw Error('Maksimal 100 proyek pribadi.');const p=cleanProject({...data,id:'custom-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),tasks:data.tasks.split('\n')});state.custom.push(p);state.saved.push(p.id);state=normalize(state,demos);persist(`Created ${p.name}`);$('#project-editor').close();navigate('workspace');showDetail(p.id)}else if(e.target.id==='record-form'){const id=e.target.dataset.id;state.records[id]={...data,dossier:cleanDossier(data)};state=normalize(state,demos);if(!state.saved.includes(id))state.saved.push(id);persist(`Saved research: ${project(id).name}`);render();showDetail(id);toast('Research saved.')}else if(e.target.id==='review-form'){const p=project(e.target.dataset.id);state.reviews.unshift(cleanReview({...data,projectId:p.id}));state.reviews=state.reviews.slice(0,100);persist(`Added local review: ${p.name}`);render();showDetail(p.id);toast('Ulasan tersimpan lokal, belum dipublikasikan.')}else{state.name=data.name.trim()||'Museum Explorer';persist('Updated local profile');render();toast('Profile saved.')}}catch(err){let feedback=e.target.querySelector('.form-error');if(!feedback){feedback=document.createElement('p');feedback.className='notice form-error';feedback.setAttribute('role','alert');e.target.append(feedback)}feedback.textContent=err.message;toast(err.message)}});
$('#profile-top').onclick=()=>navigate('profile');$('#detail').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if([...nav.map(n=>n[0]),'calendar'].includes(id)&&id!==page){page=id;render()}});
page=[...nav.map(n=>n[0]),'calendar'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();
const tg=window.Telegram?.WebApp;if(tg?.initData){try{tg.ready();tg.expand();if(tg.isVersionAtLeast('6.1')){tg.setHeaderColor('#f5f6f7');tg.setBackgroundColor('#f5f6f7')}tg.BackButton.onClick(()=>{if($('#detail').open)$('#detail').close();else navigate('home')});tg.BackButton.show()}catch{}}

function dashboard(){const latest=all().slice(-3);return intro('Telusuri bukti.\nTentukan penilaian Anda.','Museum terbuka tentang airdrop, hasil, dan pelajarannya.')+`<section class="museum-hero"><div class="hero-editorial"><span class="eyeline">KOLEKSI UTAMA / VOL. 01</span><h2>Setiap airdrop<br>meninggalkan jejak.</h2><span class="tag-inline">Contoh fiktif · bukan kampanye nyata</span><p>Jelajahi pameran, telaah sumber dan sinyal risiko, lalu tentukan penilaian Anda. Transparansi menjadi panduan; keputusan tetap milik pengunjung.</p><div class="hero-actions"><button class="primary" data-nav="explore">Masuk ke galeri ↗</button><button class="text-btn" data-nav="archive">Telusuri arsip →</button></div></div><div class="museum-art" aria-hidden="true"><div class="museum-arch"><img src="brand.jpg" alt=""></div><span>MUSEUM TERBUKA<br>EST. 2026</span></div></section><div class="museum-principles"><span>01 / Terbuka untuk ditinjau</span><span>02 / Bukti sebelum opini</span><span>03 / Jejak yang disimpan</span></div>`+`<section class="notice" role="note"><b>Catatan riset hanya tersimpan di browser ini.</b> Tidak ada akun atau sinkronisasi cloud. Jangan masukkan data sensitif; buka Profil untuk ekspor cadangan atau menghapus data lokal. <button class="text-btn" data-nav="profile">Kelola data →</button></section>`+stats()+`<div class="section-title"><h2>Isi koleksi</h2><button class="text-btn" data-nav="explore">Semua pameran ↗</button></div><div class="grid">${latest.map(card).join('')}</div><div class="split museum-bottom"><section class="panel"><span class="eyeline">LANGKAH BERIKUTNYA</span><h3>Lanjutkan riset Anda</h3>${all().filter(p=>state.saved.includes(p.id)&&rec(p).status==='active').slice(0,3).map(row).join('')||empty('Tambahkan pameran ke Portofolio untuk memulai riset pribadi.')}<button class="text-btn" data-nav="workspace">Buka portofolio →</button></section><section class="panel"><span class="eyeline">SUARA PENGUNJUNG</span><h3>Museum dengan banyak sudut pandang.</h3><p>Baca metodologi penilaian dan tulis catatan ulasan pribadi. Ulasan publik, vouch, dan slash belum diaktifkan.</p><button class="text-btn" data-nav="voices">Baca metodologi →</button></section></div>`}
function dossierView(p){const d=rec(p).dossier;return `<section class="dossier"><div class="section-title"><h3>Dossier transparansi</h3><span class="trust-unrated">◌ Belum dinilai</span></div><p>Skor publik 0–2800 memerlukan bukti dan metode terverifikasi. Data kosong tidak dianggap aman atau berisiko.</p><dl>${[['Tahap kampanye',CLAIM_STAGES[d.stage]],['Audit kontrak',d.audit],['Aktivitas tim publik',d.team],['Treasury / likuiditas',d.treasury],['Bukti on-chain / snapshot',d.chainEvidence],['Sinyal risiko',d.risks],['Tinjauan pribadi terakhir',d.checkedAt],['Hasil distribusi',d.outcome]].map(([key,value])=>`<div><dt>${key}</dt><dd>${esc(value||'Belum ada bukti tercatat')}</dd></div>`).join('')}</dl><small>Catatan diisi pemilik, tersimpan lokal di browser, dan belum diverifikasi.</small></section>`}
function dossierForm(p){const d=rec(p).dossier;return `<details class="evidence-editor"><summary>Ubah dossier transparansi</summary><label>Tahap kampanye<select name="stage">${Object.entries(CLAIM_STAGES).map(([k,v])=>`<option value="${k}" ${d.stage===k?'selected':''}>${v}</option>`).join('')}</select></label>${[['audit','Audit · sumber / temuan',500],['team','Aktivitas tim · sumber / temuan',500],['treasury','Treasury / likuiditas · sumber / temuan',500],['chainEvidence','On-chain / snapshot · bukti',500],['risks','Sinyal risiko · pengamatan',1000],['outcome','Hasil distribusi · bukti',1000]].map(([key,title,max])=>`<label>${title}<textarea name="${key}" maxlength="${max}" rows="2">${esc(d[key])}</textarea></label>`).join('')}<label>Tanggal tinjauan pribadi<input type="date" name="checkedAt" value="${d.checkedAt}"></label></details>`}
function reviewForm(p){return `<section class="visitor-notes"><h3>Catatan pengunjung · tersimpan lokal</h3><p>Ulasan tersimpan di browser ini. Belum ada publikasi, voting komunitas, atau reputasi on-chain.</p>${state.reviews.filter(r=>r.projectId===p.id).slice(0,5).map(r=>`<blockquote><b>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</b><p>${esc(r.text)}</p><small>Local note · ${esc(new Date(r.at).toLocaleDateString('id-ID'))}</small></blockquote>`).join('')}<form id="review-form" data-id="${esc(p.id)}"><label>Penilaian pribadi<select name="rating">${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select></label><label>Pengamatan Anda<textarea name="text" maxlength="2000" rows="3" required></textarea></label><button class="secondary">Simpan ulasan lokal</button></form></section>`}
function voices(){return intro('Many voices. Visible evidence.','Penilaian pengunjung memperkaya exhibit, tanpa menyembunyikan informasi dari galeri.')+`<section class="panel methodology"><span class="eyeline">TRUST SCORE / WHITEPAPER FRAMEWORK</span><h2>A score needs a visible foundation.</h2><p>Whitepaper mengusulkan audit, usia proyek, treasury, aktivitas tim, bukti on-chain, serta masukan komunitas. Implementasi saat ini menyimpan dossier pribadi; tidak menghasilkan skor kredibilitas publik.</p><div class="score-scale">${TRUST_BANDS.map(([range,label])=>`<div><b>${range}</b><small>${label}</small></div>`).join('')}</div><div class="notice">Rentang di atas adalah rancangan whitepaper, bukan rating exhibit yang sudah diverifikasi. Skor tidak menjamin keamanan atau reward.</div></section><div class="split"><section class="panel"><h3>Vouch & slash</h3><p>Direncanakan dalam whitepaper. Belum ada staking token, pemotongan reputasi, kontrak, atau transaksi keuangan yang aktif.</p><span class="tag-inline">Roadmap · not active</span></section><section class="panel"><h3>Public visitor voice</h3><p>Memerlukan identitas terverifikasi, penyimpanan bersama, kebijakan sengketa, dan perlindungan manipulasi sebelum dapat dibuka.</p><span class="tag-inline">Roadmap · not active</span></section></div><section class="panel"><h3>Your local review notebook</h3>${state.reviews.length?state.reviews.map(r=>`<article class="review-item"><button class="text-btn" data-open="${esc(r.projectId)}">${esc(project(r.projectId)?.name||'Exhibit')} ↗</button><b>${'★'.repeat(r.rating)}</b><p>${esc(r.text)}</p><small>Private browser note · ${esc(new Date(r.at).toLocaleDateString('id-ID'))}</small></article>`).join(''):empty('Buka detail exhibit untuk menulis ulasan pribadi pertama Anda.')}</section>`}
function sourceGate(id){const p=project(id);if(!p?.website)return;const u=new URL(p.website);if(!$('#source-gate'))document.body.insertAdjacentHTML('beforeend','<dialog id="source-gate"></dialog>');const gate=$('#source-gate');gate.innerHTML=`<div class="detail-body"><span class="eyeline">BEFORE YOU LEAVE THE MUSEUM</span><h2>Inspect the destination.</h2><p>Anda akan membuka sumber eksternal di tab baru.</p><div class="source-host">${esc(u.hostname)}</div><p class="source-url">${esc(u.href)}</p><ul>${sourceSignals(p.website).map(s=>`<li>${esc(s)}</li>`).join('')}</ul><div class="notice">Jangan berikan seed phrase atau private key. Periksa domain, izin wallet, dan rincian transaksi secara mandiri.</div><div class="data-actions"><button class="secondary" id="cancel-source">Return to exhibit</button>${u.username||u.password?'':`<a class="primary" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Open external source ↗</a>`}</div></div>`;gate.querySelector('#cancel-source').onclick=()=>gate.close();gate.showModal()}

function invite(){const share=createInvitePayload(location.href);return intro('Undang dengan transparan.','Bagikan Museum secara sukarela; tidak ada atribusi atau hadiah referral saat ini.')+`<section class="panel invite-panel"><span class="eyeline">UNDANGAN / REFERRAL</span><h2>Bagikan riset, bukan janji reward.</h2><p>Tautan ini hanya membuka halaman utama Museum. Tidak ada kode referral, data pribadi, atau identitas yang ditambahkan ke tautan.</p><label for="invite-url">Tautan ajakan<input id="invite-url" type="url" value="${esc(share.url)}" readonly></label><div class="invite-actions"><button class="primary" id="share-invite" type="button">Bagikan tautan</button><button class="secondary" id="copy-invite" type="button">Salin tautan</button></div></section><div class="invite-columns"><section class="panel"><h3>Yang berlaku sekarang</h3><ul><li>Tidak ada poin, uang, token, komisi, atau hadiah referral.</li><li>Aplikasi tidak menghitung klik atau konversi dan tidak memberi tahu siapa yang membuka tautan.</li><li>Tidak perlu wallet, email, data pribadi, atau pembayaran.</li></ul></section><section class="panel"><h3>Berbagi dengan bertanggung jawab</h3><ul><li>Bagikan secara sukarela kepada orang yang memang tertarik; jangan kirim spam atau pesan massal.</li><li>Jelaskan bahwa Museum berisi demo fiktif, bukan feed airdrop aktif atau rekomendasi investasi.</li><li>Jangan menjanjikan profit, eligibility, keamanan proyek, atau imbalan yang belum tersedia.</li></ul></section></div><p class="invite-note">Tautan biasa ini belum memberi atribusi kepada pengundang. Program berhadiah atau pelacakan referral memerlukan layanan server, aturan publik, perlindungan penyalahgunaan, dan kebijakan privasi tersendiri.</p>`}
function copyInvite(){const field=$('#invite-url');if(!field)return;const fallback=()=>{field.focus();field.select();const copied=document.execCommand('copy');toast(copied?'Tautan ajakan disalin.':'Pilih tautan lalu salin secara manual.')};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(field.value).then(()=>toast('Tautan ajakan disalin.')).catch(fallback);else fallback()}
function shareInvite(){const data=createInvitePayload(location.href);if(navigator.share)navigator.share(data).catch(err=>{if(err.name!=='AbortError')toast('Berbagi tidak tersedia. Anda dapat menyalin tautan.')});else copyInvite()}
function archive(){const history=all().filter(p=>['snapshot','closed','failed','risk_reported'].includes(rec(p).dossier.stage));return intro('The historical collection.','Snapshot, distribusi, kegagalan, dan risiko yang dicatat—tetap menjadi bahan pembelajaran.')+`<section class="panel"><span class="eyeline">EXHIBIT HISTORY / PERSONAL RECORDS</span><h3>Document the outcome, not just the reward.</h3>${history.length?history.map(p=>`<article class="history-exhibit"><div class="section-title"><button class="text-btn" data-open="${esc(p.id)}">${esc(p.name)} ↗</button><span class="tag-inline">${esc(CLAIM_STAGES[rec(p).dossier.stage])}</span></div><p>${esc(rec(p).dossier.outcome||'Belum ada bukti hasil distribusi yang dicatat.')}</p><small>Personal report · ${esc(rec(p).dossier.checkedAt||'Review date unknown')}</small></article>`).join(''):empty('Catat tahap snapshot, distribusi selesai, gagal, atau risiko dilaporkan di dossier exhibit agar masuk riwayat ini.')}</section>`+archiveLedger()}

function syncPanel(){const active=serverInfo?.sync&&!!window.Telegram?.WebApp?.initData;return `<section class="panel"><span class="eyeline">YOUR DATA / YOUR CONTROL</span><h3>Sinkronisasi pribadi</h3><div class="status-row"><b>Penyimpanan server</b><span>${serverInfo?.database==='ready'?'Tersedia':serverInfo?'Belum tersedia':'Memeriksa…'}</span></div><p>Ambil & gabungkan akan membaca data akun ke browser. Kirim ke cloud akan menyimpan nama, proyek, catatan, ulasan pribadi, jadwal, dan ledger ke akun Telegram Anda. Data tidak menjadi ulasan publik. Sinkronisasi berjalan hanya saat Anda menekan tombol.</p><p class="connection">${active?'Autentikasi Telegram tersedia. Ambil data terlebih dahulu untuk memperoleh revisi terbaru.':'Sinkronisasi belum aktif. Token bot proyek perlu dikonfigurasi; aplikasi lokal tetap dapat digunakan.'}</p><div class="data-actions"><button class="secondary" id="cloud-read" ${!active||syncBusy?'disabled':''}>Ambil & gabungkan</button><button class="primary" id="cloud-write" ${!active||syncBusy||cloudRevision===null?'disabled':''}>Kirim ke cloud</button></div><p class="connection">${cloudRevision===null?'Belum membaca revisi server.':'Revisi server terakhir: '+cloudRevision} · Konflik perubahan akan ditolak agar data perangkat lain tidak tertimpa.</p></section>`}
async function cloudAction(action){if(syncBusy)return;const initData=window.Telegram?.WebApp?.initData;if(!serverInfo?.sync||!initData)return toast('Sinkronisasi belum tersedia.');if(action==='write'&&cloudRevision===null)return toast('Ambil data server terlebih dahulu.');syncBusy=true;render();try{const headers={'X-Telegram-Init-Data':initData};const options={headers};if(action==='write'){headers['Content-Type']='application/json';headers['If-Match']=String(cloudRevision);options.method='PUT';options.body=JSON.stringify(state)}const response=await fetch('/api/me/state',options);const data=await response.json();if(!response.ok){if(response.status===409){cloudRevision=null;throw Error('Data server berubah. Ambil & gabungkan kembali sebelum mengirim.')}if(response.status===401)throw Error('Sesi Telegram kedaluwarsa. Buka ulang Mini App.');throw Error('Sinkronisasi gagal: '+(data.error||response.status))}if(action==='read'&&data.state){state=mergeBackup(state,backup(JSON.stringify(data.state),demos),demos);persist('Merged private cloud backup')}cloudRevision=data.revision;toast(action==='read'?'Data server dibaca dan digabungkan.':'Data tersimpan ke akun Anda.')}catch(err){toast(err.message)}finally{syncBusy=false;render()}}
document.addEventListener('click',e=>{if(e.target.closest('#cloud-read'))cloudAction('read');if(e.target.closest('#cloud-write'))cloudAction('write')});
fetch('/api/capabilities').then(async r=>{if(!r.ok)throw Error();serverInfo=await r.json();if(page==='profile')render()}).catch(()=>{serverInfo={database:'unavailable',sync:false};if(page==='profile')render()});
